    \captionsetup{width=1\textwidth, font=small}
\caption{Illustration of the one-dimensional structure induced by a Krylov basis for the bath single-particle space. Each block represents a group of annihilation operators, and an edge indicates that the Hamiltonian contains coupling terms between the corresponding blocks.\\
\textbf{(a) Krylov basis.} We choose a bath single-particle basis $\{g_j\}_j$ consistent with the Krylov shells $W_0,W_1,\ldots$. When $H$ is expressed in terms of the annihilation operators $\{a(g_j)\}_j$, it has a one-dimensional block structure. Each block has  at most $2m$ modes. The impurity couples only to the first block through the  hybridization terms 
$\{O_j^\dagger a(\mu_j)\}_j$, 
and each subsequent block couples only to its neighboring blocks.\\
\textbf{(b) Bandwise Krylov basis.} We first decompose the bath single-particle space into logarithmically spaced energy bands $[\omega_\ell,2\omega_\ell)$ and construct a Krylov basis separately within each band. The complexity of our classical simulation depends on
$\kappa\coloneqq\sum_\ell \xi_\ell\omega_\ell^{-2}$,
where $\xi_\ell$ measures the squared hybridization strength in band $\ell$. For the original impurity--bath partition, the hybridization vectors $\Pi_\ell\mu_j$ need not be small relative to $\omega_\ell$. We therefore enlarge the impurity by including the first Krylov block from each band. The  coupling between the enlarged impurity and the residual bath is an off-diagonal block of the bath matrix restricted to band $\ell$ and has norm at most $2\omega_\ell$. Consequently, $\xi_\ell/\omega_\ell^2=O(m)$ for each band, and hence $\kappa$ is controlled.\\
\textbf{Note on renaming the operators.} After choosing the bandwise Krylov basis, we relabel the enlarged-impurity modes as $\{b_j\}_j$ and the residual-bath modes as $\{a_j\}_j$. 
}\label{fig:1D} 
 \end{figure}

\subsection{One-dimensional structure via block tridiagonalization}\label{sec:1D_from_block_tri}
We first explain
that, to obtain a one-dimensional structure, it suffices to find a unitary that block tridiagonalizes the quadratic bath term.
Recall the hybridization form of the Hamiltonian in Eq.~\eqref{eq:impurity_model_hyb}. For the moment, we replace $E_0$ by a placeholder Hermitian matrix $E_*$ acting on a subspace $W_*$ of the bath single-particle space,  project each $\mu_{j}$ onto $W_*$ and denote the resulting vector by $\mu_{j*}$. Denote the resulting Hamiltonian by $H_*$,

\begin{equation}
    H_*
    = K_0+ 
    \dE(E_*)
    +
    \sum_{j=1}^{2m}
    \left(
        a^\dagger(\mu_{j*})O_j
        +
        O_j^\dagger a(\mu_{j*})
    \right).\label{eq:hyb_placeholder}
\end{equation}

Denote $W_{*0}\coloneqq \spn\{\mu_{1*},\ldots,\mu_{2m*}\}$ and $s_0\coloneqq\dim(W_{*0})\leq 2m$.
To transform the Hamiltonian $H_*$ into a one-dimensional structure, 
it suffices to find an orthonormal basis of the bath single-particle subspace $W_*$, whose basis vectors form the columns of an isometry $V$,
such that  (i) the first $s_0$ column vectors of 
$V$ span a space containing the hybridization vectors $\{\mu_{1*},\ldots,\mu_{2m*}\}$,  and  (ii) the resulting matrix is block tridiagonal,
\begin{align}
    V^\dagger E_* V  = 
\begin{pmatrix}
P_{0} & Q_{0}^\dagger & 0 & 0 \\
Q_{0} & P_{1} & Q_{1}^\dagger & 0\\
0& Q_{1} & P_{2} & \ddots\\
0& 0 & \ddots & \ddots 
\end{pmatrix},\label{eq:block-tridiag}
\end{align}
where $P_0\in \C^{s_0\times s_0}$  and all subsequent blocks  $P_k$ are of size at most $2m
\times 2m$. The norms  $\|P_j\|, \|Q_j\|$ are bounded by $\|E_*\|$ since the corresponding blocks are submatrices of $V^\dagger E_* V$. 
To see why Eq.~(\ref{eq:block-tridiag}) leads to a one-dimensional structure, suppose we have found such a $V$ and denote its column vectors by $\{g_j\}_j$. Define a new set of annihilation operators as $\{a(g_j)\}_j$. Then, in this new basis, $H_*$ is re-expressed by
\begin{align}
    H_*= K_0  + \sum_{j,k} \langle e_j,\,(V^\dagger E_* V)\, e_k\rangle \,\, a(g_k)^\dagger a(g_j) + \sum_{j=1}^{2m} \left( a^\dagger( \mu_{j*}) O_j +  O_j^\dagger a( \mu_{j*}) \right)
\end{align}
where $K_0$ and $\{O_j\}_j$ are unchanged since we only change the bath single-particle basis.
The Hamiltonian $H_*$ has a one-dimensional structure as in Figure \ref{fig:1D} (a) due to the block-tridiagonal form of $V^\dagger E_*V$ in Eq.~(\ref{eq:block-tridiag}):
More specifically,
let $I_k$ denote the set of column indices of $V$ corresponding to the
diagonal block $P_k$ in Eq.~\eqref{eq:block-tridiag}.
We group the annihilation operators
$\{a(g_j):j\in I_k\}$ as the $k$th \textit{bath-mode group}, which
corresponds to the $(k+1)$st square block in Figure~\ref{fig:1D}(a). The block-tridiagonal form of $V^\dagger E_*V$ in Eq.~(\ref{eq:block-tridiag}) implies that the bath blocks only couple to their neighbors. Besides, since  each hybridization vector $\mu_{j*}$ lies in the span of $g_1,\ldots,g_{s_0}$,   the
hybridization term $a^\dagger( \mu_{j*}) O_j +  O_j^\dagger a( \mu_{j*})$  couples the impurity only to the first bath block. 

Moreover, by assumption the blocks $\{P_k\}_{k\geq 0}$ are each of size at most $2m\times 2m$, so the size of each bath group is $|I_k|\leq 2m$.

\paragraph{Block tridiagonalization via orthogonalizing a Krylov sequence.}
To construct the isometry $V$  that block tridiagonalizes $E_*$ and whose first few columns span a space containing the hybridization vectors, one could use the  standard block Lanczos tridiagonalization, or equivalently, orthogonalize a Krylov sequence.

More specifically, let $W_{*0}$ denote the space spanned by the hybridization vectors, and define the depth-$d$ Krylov space $K_{*d}$ by successively applying $E_*$ to $W_{*0}$:
\begin{align}
    W_{*0}
    \coloneqq
    \operatorname{span}\{\mu_{1*},\ldots,\mu_{2m*}\},\qquad
    K_{*d}
    \coloneqq
    \operatorname{span}\{W_{*0},E_*W_{*0},\ldots,E_*^dW_{*0}\}.
\end{align}

The column vectors of $V$ are obtained by successively orthogonalizing the Krylov spaces. More precisely, set $K_{*,-1}\coloneqq\{0\}$ and define the depth-$d$ Krylov shell spaces
\begin{align}
    W_{*d}\coloneqq K_{*d}\ominus K_{*,d-1},\qquad d\geq 1; \qquad  W_{*,-1}\coloneqq\{0\}.
\end{align}

Choose an orthonormal basis for each $W_{*d}$, and let $\{g_j\}_j$ denote the union of these bases. Without loss of generality, we may assume that $\{g_j\}_j$ spans the whole space $W_*$.\footnote{If $\{g_j\}_j$ does not span the full space $W_*$, let
$M$ be the orthogonal complement of $\operatorname{span}\{g_j\}_j$
in $W_*$. Since $M$ is invariant under $E_*$ and is orthogonal to all
hybridization vectors, there is no coupling in the Hamiltonian between
the modes in $M$ and the remaining modes. Moreover, since $H_*$ has
even parity, under the corresponding
Fock-space factorization, the Hamiltonian therefore decomposes as
$H_*=H_{\mathrm{active}}\otimes \I
+\I\otimes \dE(E_*|_M).$
Hence the modes in $M$ form a decoupled free-fermion sector that can be
treated separately, and we assume $M=\{0\}$ for simplicity.}
Let $V$ denote the isometry whose columns are the basis vectors constructed above,
\begin{align}
    V=[\ldots\,\, ,g_j, \,\,\ldots]
\end{align}

Then  we have
\begin{lemma}[One-dimensional structure]\label{lem:krylov_1D}
We have  $\dim(W_{*d})\leq 2m$ for all $d\geq 0$. Besides, 
\begin{align}
    E_*W_{*d}
    \subseteq
    W_{*,d-1}\oplus W_{*d}\oplus W_{*,d+1}. 
\end{align}
Thus, when the columns of $V$ are ordered according to $W_{*0},W_{*1},\ldots$, the matrix $V^\dagger E_*V$ has the block-tridiagonal form in Eq.~\eqref{eq:block-tridiag}.
\end{lemma}
\begin{proof} 
The dimension bound for $W_{*d}$ comes directly from its definition and the fact that the dimension of $W_{*0}$ is smaller than $2m$.  
To prove the inclusion, first 
note that by definition, $W_{*d}\subseteq K_{*d}$, and hence 
$E_*W_{*d}\subseteq K_{*,d+1}.$ 

For $d\geq 1$, let $u\in W_{*d}$ and $v\in K_{*,d-2}$. Since $E_*$ is Hermitian, we have $
\langle v,E_*u\rangle = \langle E_*v,u\rangle. $
But $E_*v\in K_{*,d-1}$, while $u\in W_{*d}$ is orthogonal to $K_{*,d-1}$. Therefore 
\begin{align} 
\langle v,E_*u\rangle=0. 
\end{align} 

Thus $E_*W_{*d}$ is contained in $K_{*,d+1}$ and orthogonal to $K_{*,d-2}$, which proves the Lemma for $d\geq 1$.   The case $d=0$ follows directly from $E_*W_{*0}\subseteq K_{*1}$.
Finally, with respect to the decomposition
\[
    W_*=\bigoplus_{d\geq 0}W_{*d},
\]
the inclusion above implies that $V^\dagger E_*V$ is block tridiagonal, as in Eq.~\eqref{eq:block-tridiag}.
\end{proof}


\subsection{Bandwise Krylov basis}\label{sec:band_krylov}

Recall that $\omega$ denotes the lower bound for single-particle energy after preprocessing, i.e.
$$0<   \omega \I \leq E_0 \leq \es \I.$$

In Section \ref{sec:1D_from_block_tri},
for the Hamiltonian with placeholder notation in Eq.~(\ref{eq:hyb_placeholder}), 
 we explained 
how to construct a single-particle basis for $W_*$ so that $H_*$ is transformed to the desired one-dimensional structure. 
If we set $E_*=E_0$, $\mu_{j*}=\mu_j$, and $W_*=W_{\mathrm{bath}}$, we could get a single-particle basis $\{g_j\}_j$ (the \textit{Krylov basis}) that  transforms the impurity Hamiltonian $H$ into a one-dimensional structure, as illustrated in Figure~\ref{fig:1D}(a). 
However, the resulting complexity of the classical simulation is exponential in $\omega^{-1}$, and is therefore inefficient when $\omega$ is small.

We instead use a bandwise Krylov space, which treats different energy bands of $E_0$ separately.
Partition the spectrum of $E_0$ into logarithmically spaced bands,
\begin{align}
    [\omega_\ell,2\omega_\ell),\qquad
    \omega_\ell=2^\ell\omega,\qquad
    0\leq\ell\leq L\coloneqq
    \left\lceil\log_2\frac{\es}{\omega}\right\rceil.
    \label{eq:L}
\end{align}

Let $W_\ell$ be the space spanned by eigenvectors of $E_0$
with eigenvalues in $[\omega_\ell,2\omega_\ell)$, and let
$\Pi_\ell$ be the corresponding projector.
Since $\sum_\ell \Pi_\ell$ is the identity map in the bath single-particle space, one could rewrite Eq.~(\ref{eq:impurity_model_hyb}) 
as
\begin{equation}
    H
    = K_0+ 
    \sum_\ell\left( \dE( \Pi_\ell E_0)
    +
    \sum_{j=1}^{2m}
    \left(
        a^\dagger(\Pi_\ell \mu_j)O_j
        +
        O_j^\dagger a(\Pi_\ell \mu_j)
    \right)\right).\label{eq:hyb_strength_original}
\end{equation}

Applying the constructions in Section~\ref{sec:1D_from_block_tri}
to every $\ell$, with
\begin{align}
    E_*\coloneqq E_{(\ell)}\coloneqq\Pi_\ell E_0,\qquad
    \mu_{j*}\coloneqq\Pi_\ell\mu_j,\qquad
    W_*\coloneqq W_\ell,
    \label{eq:hyb_bandwise}
\end{align}
we denote the resulting Krylov shell spaces and their orthonormal bases by
\begin{align}
\text{Krylov shell spaces:}\,\,\, W_{\ell,d}, \,\,\,d\geq 0;\qquad \text{Orthonormal basis of } W_\ell=\bigoplus_{d\geq 0} W_{\ell d}\text{:}\,\,\, \{g_{\ell j}\}_j.\label{eq:Wld}
\end{align}

For each band $\ell$, the basis vectors $\{g_{\ell j}\}_j$ are ordered so that those spanning $W_{\ell,0}$ come first, followed by those spanning $W_{\ell,1}$, then $W_{\ell,2}$, and so on.  Combining the bases from all bands,  we obtain the orthonormal basis   $\{g_{\ell j}\}_{\ell,j}$ for the entire bath single-particle space.

Define $V_\ell=[g_{\ell1},\ldots,g_{\ell j},\ldots]$. Then $V_\ell^\dagger E_{(\ell)} V_\ell$ has the block tridiagonal form given in Eq.~(\ref{eq:block-tridiag}). Thus the impurity model $H$ in terms of $\{a(g_{\ell j})\}_{\ell j}$ has a bandwise one-dimensional structure as in Figure \ref{fig:1D} (b).

We call this basis $\{f_j\}_j\coloneqq\{g_{\ell j}\}_{\ell j}$ the \textit{bandwise Krylov basis}.

\subsection{Bandwise hybridization form with an enlarged impurity} 

\paragraph{Relabel annihilation operators.}\label{sec:enlarged_impurity}

As in Figure~\ref{fig:1D}(b), we enlarge the impurity to include the first Krylov shell in each band. In other words, we call
$\{a(e_j)\}_{j=1}^m\cup\{a(g_{\ell j})\}_{\ell;\,j\leq \dim(W_{\ell 0})}$
the \textit{enlarged impurity modes}, and call the remaining operators
$\{a(g_{\ell j})\}_{\ell;\,j>\dim(W_{\ell 0})}$
the \textit{residual bath modes}. We explain the reason for this partition below. To simplify the notation, throughout the remainder of the manuscript, we relabel the enlarged-impurity modes as $\{b_k\}_{k\geq 1}$ and the residual-bath modes as $\{a_i\}_{i\geq 1}$. Accordingly, we also represent vectors in the enlarged-impurity single-particle space $W_{\mathrm{imp}}\bigoplus_\ell W_{\ell,0}$ and the residual-bath single-particle space $\bigoplus_{\ell;\,d\geq 1} W_{\ell,d}$ by viewing the basis $\{e_j\}_{j=1}^m\cup\{g_{\ell j}\}_{\ell,j}$ as the standard basis. For any vector $v$ in the enlarged impurity single-particle space,  define $b(v)\coloneqq\sum_k v_k b_k$.  

The reason for enlarging the impurity is to reduce the cost of our classical simulation algorithm, which will heavily rely on the interaction strength between the ``impurity'' part and the ``bath'' part. Note that we do not have much control of the interaction strength between the original impurity and the bath part:  $\|\Pi_\ell \mu_j\|$ in Eq.~(\ref{eq:hyb_strength_original}) need not be small relative to $\omega_\ell$, since $\mu_j$ could be arbitrary. 

In contrast, we have good control of the interaction strength between the first and second bath blocks in Figure \ref{fig:1D}(b), which is the interaction strength between the enlarged impurity and the residual bath. Let $s_{\ell 0}$ and $s_{\ell 1}$ be the dimensions of the first two Krylov shells $W_{\ell 0}$ and $W_{\ell 1}$, respectively.  
The corresponding interaction terms in the Hamiltonian $H$ can be written as
\begin{align}
    \sum_{\ell=0}^L \sum_{j=1}^{r_\ell}
    \sigma_{\ell j}
    \left(
        a^\dagger(u_{\ell j})b(v_{\ell j})
        +
        b^\dagger(v_{\ell j})a(u_{\ell j})
    \right),
    \qquad
    |\sigma_{\ell j}|\leq 2\omega_\ell,
    \label{eq:hyb_first_second}
\end{align}
where $\{u_{\ell j}\}_j$ and $\{v_{\ell j}\}_j$ are orthonormal vectors in $W_{\ell 1}$ and $W_{\ell 0}$, respectively, and $r_\ell\leq 2m$: 
note that $V_\ell^\dagger E_{(\ell)} V_\ell$ has the block tridiagonal form in Eq.~\eqref{eq:block-tridiag}, where the off-diagonal block $Q_{\ell 0}$ connecting $W_{\ell 0}$ and $W_{\ell 1}$ satisfies
    $\|Q_{\ell 0}\|\leq \|E_{(\ell)}\|\leq 2\omega_\ell.$
Since $\dim(W_{\ell 0})\leq 2m$, the quantity $r_\ell\coloneqq\rank(Q_{\ell 0})$ satisfies the same bound.    
Taking the singular-value decomposition
\begin{align}
    Q_{\ell 0}
    =
    \sum_{j=1}^{r_\ell}
    \sigma_{\ell j}
    u_{\ell j}v_{\ell j}^\dagger, \qquad r_\ell\leq 2m,
\end{align}
where 
$\sigma_{\ell j}\leq\|Q_{\ell 0}\|\leq2\omega_\ell$, 
we obtain Eq.~\eqref{eq:hyb_first_second}. 

Putting these preprocessing steps together, we arrive at the following bandwise hybridization form with enlarged impurity, which we use throughout the remainder of the manuscript.

