\section{Threshold and Enhancement}
\label{sec:threshold}
Consider the setup in Remark \ref{rem:setup} and the noise model reduction in Theorem \ref{thm:noise-model-reduction}.
In this section, we shall show that the effective seed level errors $E\super{0}(t),\mu\super{0}(t^+)$ are jointly local stochastic with rate $\ll p$.

\subsection{Active History}

By Theorem \ref{thm:noise-model-reduction}, the effective error at time $t$ is the noisy descent of $E\super{\ell} = e\super{\ell} + \hat{\cE}(\mu\super{\ell}_-)$ relative to $\mu_+\super{\ell}$ where 
\begin{equation}
    e\super{\ell} =e\super{\ell}(t), \quad \mu_\pm\super{\ell} = \mu\super{\ell}(t^\pm)
\end{equation}
so we have omitted the time $t$ dependence for simplicity.
Note that $\cE(\mu_-\super{\ell})$ has a special \textit{lifted} structure, and thus it warrants a slight variation of the RG syndrome subgraph in Definition \ref{def:RG-subgraph}.
For later reference, the corresponding noisy syndrome is
\begin{equation}
    \label{eq:t-round-syndrome}
    \noisy{\sigma}\super{\ell} = \delta E\super{\ell} + \mu_+\super{\ell}
\end{equation}
\begin{lemma}[Active History]
    \label{lem:active-history}
    Let $\bm{\rho}$ be a sequence of $i$-level valid syndromes with lifted syndrome $\Sigma \bm{\rho}$, and let $\mu\super{\ell}$ be an $\ell$-level syndrome. 
    Let $\noisy{\sigma}\super{\ell} = \mu\super{\ell} + \Sigma \bm{\rho}$ have noisy history $\noisy{\bm{\sigma}}$. Then
    \begin{equation}
        \noisy{\sigma}\super{i} = \noisy{a}\super{i} + \iota \left(\sum_{j<i} \rho\super{j}\right)
    \end{equation}
    where $\noisy{a}\super{i}$ is initialized with $\noisy{a}\super{\ell} = \mu\super{\ell} +\rho\super{\ell}$ and defined inductively as
    \begin{equation}
        \noisy{a}\super{i-1} = \desc \rep \noisy{a}\super{i} + \rho\super{i-1}
    \end{equation}
    With slight abuse of notation\footnote{Technically, $\noisy{\bm{a}}$ depends on both $\bm{\rho},\mu\super{\ell}$ and not just on $\noisy{\bm{\sigma}}$}, we refer to $\noisy{\bm{a}} = (\noisy{a}\super{i})$ as the \textbf{active history} of $\noisy{\bm{\sigma}}$, since the cleaning $f(\rep \noisy{\sigma}\super{i}) = f(\rep \noisy{a}\super{i})$.
\end{lemma}

\begin{proof}
    Follows from the passthrough property of the cleaning in Definition \ref{def:cleaning} and the valid syndrome invariance of the syndrome repair.
\end{proof}

\begin{definition}[Active Subgraph]
    Let $\bm{\rho}$ be a sequence of valid syndromes and $\noisy{\sigma}\super{\ell} = \mu\super{\ell} + \Sigma\bm{\rho}$ induce history $\noisy{\bm{\sigma}}$, cleanings $\bm{f}$ and active history $\noisy{\bm{a}}$.
    Then the \textbf{active} RG syndrome subgraph $\cG_{\rm act} (\noisy{\bm{\sigma}})$ is the subgraph induced by vertices
    \begin{equation}
        \cG_{\rm act} (\noisy{\bm{\sigma}}) = \noisy{a}\super{0}\cup \bigcup_{i \ge 1} \sh (\noisy{a}\super{i} \cup \rep\noisy{a} \cup f\super{i} \cup \delta f\super{i})
    \end{equation}
    Note that $\cG(\noisy{\bm{\sigma}})$ in Definition \ref{def:RG-subgraph} does not include $\noisy{\sigma}\super{0}$ explicitly since it is implicitly included in the shadows, but for the active subgraph, $\rho\super{0}$ changes this.
\end{definition}

\begin{lemma}[Witness Equivalence]
    \label{lem:witness-equivalence}
    Let $\noisy{\sigma}\super{\ell} = \mu\super{\ell} + \Sigma \bm{\rho}$ where $\bm{\rho}$ is a sequence of valid syndromes, and $\noisy{\bm{\sigma}}$ denote its history.
    Then the RG subgraph $\cG(\noisy{\bm{\sigma}})$ has a witness iff the active RG subgraph $\cG_{\rm act}(\noisy{\bm{\sigma}})$ has a witness.
\end{lemma}

\begin{proof}
    By Lemma \ref{lem:active-history}, $\noisy{\sigma}\super{0} = \noisy{a}\super{0}$ and thus the statement follows.
\end{proof}

Unlike $\cG(\noisy{\bm{\sigma}})$, the witness of $\cG_{\rm act}(\noisy{\bm{\sigma}})$ may be small, since it does not necessarily extend to the top level, e.g., only $\rho\super{0}\ne 0$.
However, such sources can be \textit{attached} to connected components of $\cG(\bm{\rho})$.
In the case of Eq. \eqref{eq:t-round-syndrome}, the goal is thus to estimate the size of the \textit{temporal} subgraph, i.e., the active subgraph + attachments due to $\bm{\mu}_\pm$, which we postpone to the next subsection.

\begin{lemma}[Cell-Layer Invariance]
    \label{lem:active-cell-layer-invariance}
    Let $\bm{\rho}$ is a sequence of valid syndromes and $\noisy{\sigma}\super{\ell} = \mu\super{\ell} +\Sigma\bm{\rho}$ have history $\noisy{\bm{\sigma}}$ and active history $\noisy{\bm{a}}$.
    Let $\cK$ be a connected component of the active RG subgraph $\cG_{\rm act} (\noisy{\bm{\sigma}})$. 
    If $i\in [\ell)$, then
    \begin{equation}
        \noisy{a}\super{i}|_{\cK} = \noisy{a}\super{i}|^{\cK}
    \end{equation}
    For notation consistency, we also write $\noisy{a}\super{0}|^{\cK} = \noisy{a}\super{0}|_{\cK}$.
\end{lemma}
\begin{proof}
    Similar to Lemma \ref{lem:cell-layer-invariance} and thus omitted.
\end{proof}
\begin{lemma}[Correction Invariance]
    \label{lem:active-correction-invariance}
    Let $\bm{\rho}$ is a sequence of valid syndromes and $\noisy{\sigma}\super{\ell} = \mu\super{\ell} +\Sigma\bm{\rho}$ have history $\noisy{\bm{\sigma}}$ and active history $\noisy{\bm{a}}$.
    Let $\cK$ be a connected component of the active RG subgraph $\cG_{\rm act} (\noisy{\bm{\sigma}})$. 
    If $i\in [\ell]$, then $\dnum^{\cK} \rep \noisy{a}\super{i}$ is clean and
    \begin{equation}
        \dnum^{\cK} f(\rep \noisy{a}\super{i}) = f(\dnum^{\cK} \rep \noisy{a}\super{i}), \quad \dnum^{\cK}\delta f(\rep \noisy{a}\super{i}) = \delta f( \dnum^{\cK} \rep \noisy{a}\super{i})
    \end{equation}
    In particular,
    \begin{equation}
        \dnum_{\cK} \desc \rep \noisy{a} = \desc \dnum^{\cK}\rep\noisy{a}\super{i}
    \end{equation}
\end{lemma}
\begin{proof}
    Follows similarly as in Lemma \ref{lem:correction-invariance}.
\end{proof}

\begin{lemma}[Equivalent Repair]
    \label{lem:equivalent-repair}
    Let $\bm{\rho}$ be valid syndromes, $\bm{\mu}$ be the history of $\mu\super{\ell}$, and $\noisy{\bm{a}}$ be the active history of $\noisy{\sigma}\super{\ell} = \mu\super{\ell} +\Sigma \bm{\rho}$.
    Then $\noisy{a}\super{i},\mu\super{i}$ differ by a valid syndrome for all $i$. In particular, the syndrome repair satisfies
    \begin{equation}
        \nu( \noisy{a}\super{i} ) = \nu (\mu\super{i} )
    \end{equation}
\end{lemma}
\begin{proof}
    By definition, $\noisy{a}\super{\ell} = \mu\super{\ell} + \rho\super{\ell}$ satisfies the statement.
    Let us now proceed by induction and note that
    \begin{align}
        \noisy{a}\super{i-1} &=\desc \rep \noisy{a}\super{i} + \rho\super{i-1} \\
        &= \desc (\rep \mu\super{i} + \im \delta) + \im \delta \\
        &= \desc \rep \mu\super{i} + \im \delta \\
        &= \mu\super{i-1} + \im \delta
    \end{align}
    where we used the fact that $\desc$ is linear on clean syndromes modulo stabilizers. The statement then follows by induction.
\end{proof}
\begin{lemma}[Component Size]
    \label{lem:active-component-size}
    Let $\bm{\rho}$ is a sequence of valid syndromes and $\noisy{\sigma}\super{\ell} = \mu\super{\ell} + \Sigma \bm{\rho}$ have history $\noisy{\bm{\sigma}}$ and active history $\noisy{\bm{a}}$. Let $\cK$ be a connected component of the active RG subgraph $\cG_{\rm act} (\noisy{\bm{\sigma}})$. Then
    \begin{equation}
        |\cK| = O\left(|\mu\super{i}|^{\cK} +\sum_{i=0}^{\ell} |\rho\super{i}|^{\cK}\right) 
    \end{equation}
    where the constant in $O$ only depends on $\kappa,c_f,\ve$.
    Moreover,
    \begin{equation}
        (\noisy{\kappa}\super{\ell}+\kappa^{\ell}) |\mu\super{\ell}|^{\cK} + \sum_{j=0}^{\ell} \kappa^j |\rho\super{j}|^{\cK} \ge |\noisy{a}\super{0}|_{\cK}
    \end{equation}
\end{lemma}
\begin{proof}
    Similar to Lemma \ref{lem:witness-size}, we can obtain
    \begin{equation}
        |\cK\super{i}| \le (1+c_f) \frac{2}{1-\ve} |\noisy{a}\super{i}|^{\cK} + 1\{i=1\}|\noisy{a}\super{0}|_{\cK}
    \end{equation}
    By Lemma \ref{lem:active-correction-invariance} and \ref{lem:equivalent-repair}, we have
    \begin{align}
        |\noisy{a}\super{i}|^{\cK} &\le |\desc \rep \noisy{a}\super{i+1}|^{\cK} + |\rho\super{i}|^{\cK} \\
        &\le \kappa |\nu (\mu\super{i+1}) + \noisy{a}\super{i+1})|^{\cK} + |\rho\super{i}|^{\cK} \\
        &\le \kappa \frac{1+\ve}{1-\ve} |\mu\super{i+1}|^{\cK} + \kappa |\noisy{a}\super{i+1}|^{\cK} + |\rho\super{i}|^{\cK} 
    \end{align}
    By inudction, it's straightforward to check that
    \begin{equation}
        |\noisy{a}\super{i}|^{\cK} \le \frac{1+\ve}{1-\ve} \sum_{j>i} \kappa^{j-i} |\mu\super{j}| + \kappa^{\ell-i} |\mu\super{\ell}| + \sum_{j\ge i} \kappa^{j-i} |\rho\super{j}|
    \end{equation}
    By Lemma \ref{lem:noisy-contraction}, we have $|\mu\super{j}| \le \noisy{\kappa}^{\ell-j}|\mu\super{\ell}|$ and thus
    \begin{equation}
        |\noisy{a}\super{i}|^{\cK} \le  (\noisy{\kappa}^{\ell-i} + \kappa^{\ell-i}) |\mu\super{\ell}| + \sum_{j\ge i} \kappa^{j-i} |\rho\super{j}|
    \end{equation}
    Take $i=0$ and the second inequality follows.
    Also note that
    \begin{equation}
        |\cK| \le (1+c_f) \frac{2}{1-\ve} \left( \left(\frac{1}{1-\noisy{\kappa}} + \frac{1}{1-\kappa}\right)|\mu\super{\ell}|^{\cK} + \frac{1}{1-\kappa}\sum_{i=0}^{\ell} |\rho\super{i}|^{\cK}\right)
    \end{equation}
\end{proof}

\subsection{Temporal Graph}

As noted in Theorem \ref{thm:noise-model-reduction}, the seed level effective error $E\super{0}(t)$ is memory-less, i.e., only depends on adjacent time steps.
This warrants the introduction of a \textit{temporal} graph.

\begin{definition}[Temporal Graph]
    \label{def:temporal-graph}
    The \textbf{temporal} RG syndrome graph $\cJ$ is constructed by three independent copies of the RG syndrome graph $\cG$ with vertices labeled by $\cV\times \{-,0,+\}$, which correspond to the times of measurement errors and physical errors.
    In additional to the \textbf{spatial} edges in each copy of $\cG$, add the \textbf{temporal} edges $(u,0)(u',\pm)$ if $u=u'$ or $uu'$ is a spatial edge in $\cG$.
    Note that its max degree is $\Delta_{\cJ}\le 3\Delta_{\cG}+2$.
    For any subset $\cS\subseteq \cJ$, we wrte $\cS_0,\cS_\pm$ to denotes it restrictions to copies $0,\pm$ respectively.
\end{definition}

Intuitively, we shall let the active subgraph $\cG_{\rm act}(\noisy{\bm{\sigma}})$ live in the copy $\cG\times 0$. 
As discussed previously, the active subgraph may have a small witness due to the sources, which is a result of measurement errors at times $t^-$.
Hence, we will examine the subgraphs $\cG(\bm{\mu}_\pm)$ \textit{attached} to the active subgraph, which themselves live in the copies $\cG\times \pm$.

\begin{definition}[Temporal Subgraph]
    \label{def:temporal-subgraph}
    Let $e\super{\ell},\mu_\pm\super{\ell}$ be given and let $\bm{\mu}_\pm,\bm{f}_\pm$ be the history and cleaning of $\mu_\pm\super{\ell}$. 
     Define the disjoint union of qubits
    \begin{equation}
        \Lambda(e\super{\ell},\mu_-\super{\ell}) = e\super{\ell} \sqcup \bigsqcup_{i=1}^{\ell} f_-\super{i}, \quad f_-\super{i}\equiv f(\rep \mu_-\super{i})
    \end{equation}
    We say that any subset $\lambda\subseteq \Lambda$ is \textbf{admissible} relative to $e\super{\ell},\mu_-\super{\ell}$. It then defines a top level physical
    \begin{equation}
        E\super{\ell}(\lambda) = \lambda \cap e\super{\ell} + \iota \left(\sum_{i=1}^{\ell} \lambda \cap f_-\super{i}\right)
    \end{equation}
    Let $\noisy{\sigma}\super{\ell}(\lambda) = \mu_+\super{\ell} + \delta E\super{\ell}(\lambda)$ have history $\noisy{\bm{\sigma}}(\lambda)$ and active history $\noisy{\bm{a}}$.
    The \textbf{temporal} RG subgraph $\cJ(\lambda,\mu_+\super{\ell})$ is then defined as the subgraph of $\cJ$ induced by vertices in
    \begin{equation}
        \cJ(\lambda,\mu_+\super{\ell}) = \cG(\bm{\mu}_-) \sqcup \cG_{\rm act}(\noisy{\bm{\sigma}}(\lambda)) \sqcup \cG(\bm{\mu}_+)
    \end{equation}
    where we have implicitly assumed that $\cG(\bm{\mu}^\pm)$ live in copies labeled by $\pm$ and the active subgraph lives in copy $0$.
    The \textbf{terminal checks} is the collection of seed level checks
    \begin{equation}
        \cT(\lambda, \mu_+\super{\ell}) =(\noisy{a}\super{0} \times 0) \sqcup (\mu\super{0}_+\times +)
    \end{equation}
    Note that copy $-$ does not matter since we are only interested in induced seed levels errors at time steps $0,+$.
    A \textbf{temporal witness} is a connected component meeting the terminal checks.
\end{definition}

\begin{lemma}[Temporal Witness]
    \label{lem:temporal-witness-size}
    Let $\lambda$ be admissible relative to $e,\mu_-$ and $\cJ(\lambda,\mu_+\super{\ell})$ have nonempty temporal witness $\cK$ and terminal checks $\cT$.
    Then
    \begin{equation}
        \quad N(\cK)= \Omega( |\cK|), \quad |\cK| = \Omega(\noisy{\kappa}^{-\ell})|\cK\cap \cT|
    \end{equation}
    where $\Omega,O$ only depend on constants in Eq. \eqref{eq:constants}, and $N(\cK)$ denotes the \textbf{top level} weight,
    \begin{equation}
        N(\cK) = |\delta \ubar{e}\super{\ell}|^{\cK_0} + |\mu_+\super{\ell}|^{\cK_+} + |\mu_-\super{\ell}|^{\cK_-}
    \end{equation}




\end{lemma}

\begin{proof}
    By Lemma \ref{lem:active-component-size}, can upper bound the size of $|\cK_0|$ via the measurement error $|\mu_+\super{\ell}|^{\cK_0}$ and the valid syndromes $|\delta \ubar{E}\super{i}|^{\cK_0}$.
    Note that by definition, if $z\in (\delta \ubar{f}_-\super{i})|^{\cK_0}$ for $i\in [\ell)$, then $z \succ \ubar{f}_-\super{i}$.
    Since $\ubar{f}_-\super{i}\subseteq f_-\super{i}$, we see that $z\succ f_-\super{i}$ and thus $\sh z \succeq \sh f_-\super{i}$.
    Note that $\sh f_-\super{i}$ is contained in $\cG(\bm{\mu}_-)$.
    Hence, by connectivity of temporal graph, we see that
    \begin{align}
        |\delta \ubar{f}_-\super{i}|^{\cK_0} &\le \sum_{z} 1\{\sh z \in \cK_0\} \sum_{q} 1\{z\succ q\} 1\{q\in f_-\super{i}\} \\
        &\le \sum_{q} 1\{q\in f_-\super{i}|^{\cK_-}\} \sum_{z} 1\{z\succ q\} \\
        &\le \fd |f_-\super{i}|^{\cK_-}
    \end{align}
    Including the top level case, we have for $i\in [\ell]$, that
    \begin{equation}
        |\delta \ubar{E}\super{\ell}|^{\cK_0} \le |\delta e\super{\ell}|^{\cK_0}  + \fd \Delta_{\sh} (1+c_f) \frac{2}{1-\ve} \sum_{i=1}^{\ell} |\mu_-\super{i}|^{\cK_-}
    \end{equation}
    where we used the fill bound of cleaning map and the near half-fault property of the repair syndrome.
    Also note that if $z\in \mu_+\super{\ell}|^{\cK_0}$, then $\sh z\in \cK_+$ by connectivity of the temporal graph. Hence,
    \begin{equation}
        |\mu_+\super{\ell}|^{\cK_0} \le |\mu_+\super{\ell}|^{\cK_+}
    \end{equation}
    Hence, by Lemma \ref{lem:active-component-size}, 
    \begin{equation}
        |\cK_0| = O(N(\cK))
    \end{equation}
    where we used the noisy contraction.
    The case is similar for $|\cK_\pm|$ by Lemma \ref{lem:witness-size} and thus we obtain the upper bound $|\cK|= O(N(\cK))$.
    One can similarly show that $N(\cK)=\Omega(\noisy{\kappa}^{-\ell})|\cK\cap \cT|$ using Lemma \ref{lem:active-component-size}.
    A lower bound of $|\cK|$ is easily achieved by noting that $|\cK|\ge N(\cK)/\Delta_{\sh}$.


























\end{proof}

\begin{lemma}[Terminal Probability]
    \label{lem:terminal-probability}
    Let $e\super{\ell},\mu\super{\ell}_\pm$ be joint local stochastic with rate $p$. Let $\cS$ be a fixed subset of checks $z\times t$ in $\cJ$ where $t=0,+$.
    Then there exists constants $p_{\rm term},a,c>0$, depending only on the constants in Eq. \eqref{eq:constants}, such that if $p/p_{\rm term} \le a$, then
    \begin{equation}
        \Pr[\cA_{\cS}] \le  2 q^{|\cS|}, \quad q = \left(\frac{p}{p_{\rm term}}\right)^{c \noisy{\kappa}^{-\ell}}
    \end{equation}
    where $\cA_{\cS}$ is the event that there admissible $\lambda$ relative to $e\super{\ell},\mu_-\super{\ell}$ such that $\cS \subseteq \cT(\lambda,\mu_+\super{\ell})$, and $c$ is some constant.
\end{lemma}

\begin{proof}
    If $\cA_{\cS}$ occurs, then there exists a union $\cK$ of connected clusters in $\cJ$ such that $\cS\subseteq \cK$, each connected cluster in the union intersects $\cS$, and that each connected cluster is a witness of $\cJ(\lambda,\mu_+\super{\ell})$.
    If the union has fixed size $|\cK|= K$, then the number (entropy) of such unions is upper bounded by \cite{gottesman2013fault}
    \begin{equation}
        e^{|\cS|-1} (e\Delta_{\cJ})^{K-|\cS|}
    \end{equation}
    By Lemma \ref{lem:temporal-witness-size}, we see that given such a fixed union $\cK$, we have
    \begin{equation}
        |\cK| =\Omega(\noisy{\kappa}^{-\ell})  |\cS|, \quad N(\cK) =\Omega(|\cK|)
    \end{equation}
    Hence,
    \begin{equation}
        \Pr[\cA_{\cS}] \le \sum_{K=\Omega(\noisy{\kappa}^{-\ell})|\cS|} \sum_{|\cK|=K} \Pr[\cJ(\lambda,\mu_+\super{\ell}) \text{ has witnesses } \cK]
    \end{equation}
    If the union $\cK$ consists of witness of $\cJ(\lambda,\mu_+\super{\ell})$, then by Lemma \ref{lem:temporal-witness-size}, there must exist $\ell$-level syndromes $\tau_t,t=0,\pm$ with shadows $\sh \tau_t \subseteq \cK_{t}$ such that
    \begin{equation}
        \tau_0 = \delta \ubar{e}\super{\ell}|^{\cK_0}, \quad \tau_\pm=\mu_\pm\super{\ell}|^{\cK} 
    \end{equation}
    and that
    \begin{equation}
        |\tau|\equiv |\tau_0| + |\tau_+| +|\tau_-| = \Omega(|\cK|)
    \end{equation}
    In particular, we see that $\tau_0$ is covered by $e\super{\ell}$ and $\tau_\pm$ are covered by $\mu_\pm\super{\ell}$.
    Hence,
    \begin{equation}
        \Pr[\cA_{\cS}] \le \sum_{K=\Omega(\noisy{\kappa}^{-\ell})|\cS|} \sum_{|\cK|=K} \sum_{|\tau|=\Omega(|\cK|):\sh \tau_t \subseteq \cK_t}\Pr[\tau_0 \text{ covered by } e\super{\ell},\tau_\pm \text{ covered by } \mu_\pm\super{\ell}] 
    \end{equation}
    The statement the follows by Lemma \ref{lem:cover-probability}.
\end{proof}

\subsection{Noise Transfer}

\begin{lemma}[Terminal Dependence]
    \label{lem:terminal-dependence}
    Consider the notation in Definition \ref{def:temporal-subgraph}. For every $q\in \Lambda$, let $w_q\in \cC\super{0}$ denotes it seed level (composite) shadow, i.e., $w_q =\sh\circ \cdots \circ \sh q$.
    Then $\noisy{a}\super{0}(\lambda)|_z$ depends on $\lambda$ only implicitly through qubits $q$ with $w_q \preceq z$, i.e.,
    \begin{equation}
        \noisy{a}\super{0}(\lambda)|_z = \noisy{a}\super{0}(\lambda\cap \{q:w_q\preceq z\})|_z
    \end{equation}
\end{lemma}
\begin{proof}
    Let $q\in \Lambda$ be such that $w_q\not\preceq z$ and consider the symmetric difference $\lambda +q$. 
    Let $E\super{0}(\lambda)$ be the seed level noisy descent of $E\super{\ell}(\lambda)$ relative to $\mu_+\super{\ell}$.
    By Lemma \ref{lem:RG-stability}, we see that $E\super{0}(\lambda) + E\super{0}(\lambda+q)$ is supported within $\{\succeq w_q\}$.
    Also note that by Lemma \ref{lem:active-history}, we have
    \begin{equation}
        \noisy{a}\super{0}(\lambda) +\noisy{a}\super{0}(\lambda+q) = \delta  (E\super{0}(\lambda) + E\super{0}(\lambda+q))
    \end{equation}
    Hence, the difference is supported within $\{\succeq w_q\}$. 
    Since $z\not\succeq w_q$, we see that $\noisy{a}\super{0}(\lambda)|_z = \noisy{a}\super{0}(\lambda+q)|_z$ and thus the claim follows.
\end{proof}

\begin{lemma}[Admissible Cover]
    \label{lem:admissible-cover}
    Consider the notation in Definition \ref{def:temporal-subgraph} and let $\cG_Z(C\super{0})$ denote the $Z$ graph of the seed code as in Example \ref{ex:code-graph}.
    Let $\cB(e\super{\ell},\mu_\pm\super{\ell})\subseteq \cZ\super{0}$ denote the collection of seed level $z$ checks such that $\noisy{a}\super{0}(\lambda)|_z\ne 0$ for some admissible $\lambda$.
    For any $\cA \subseteq \cB$, there exists $\cS\subseteq \cA$ is a maximmaly independent (relative to the $Z$ graph) subset, then there exists admissible $\lambda\subseteq \Lambda$ such that
    \begin{equation}
        \cS\subseteq \noisy{a}\super{0}(\lambda)
    \end{equation}
\end{lemma}
\begin{proof}
    Let $\cS$ be a maximally independent subset of $\cA$ (relative to the $Z$ graph).
    For every $z\in \cS\subseteq \cB$, we can choose admissible $\lambda_z$ such that the seed level active history $\noisy{a}\super{0}(\lambda_z)|_z=1$.
    Define
    \begin{equation}
        \lambda_{\cS} = 
        \begin{cases}
            \lambda_z \cap \{q: w_q\preceq z\} & z\in \cS \\
            0 & \text{otherwise}
        \end{cases}
    \end{equation}
    Since all checks in $\cS$ are non-adjacent, we see that $\lambda_{\cS}$ is well-defined. By the terminal dependence, we see that 
    \begin{equation}
        \cS \subseteq \noisy{a}\super{0}(\lambda_{\cS})
    \end{equation}
\end{proof}
\begin{theorem}[Noise Transfer]
    \label{thm:noise-transfer}
    Consider the noise model reduction in Theorem \ref{thm:noise-model-reduction}. Then there exists $p_{\rm RG},a,c>0$, depending only on the constants in Eq. \eqref{eq:constants}, such that if the joint stochastic rate $p$ of top level errors satisfies $p/p_{\rm RG} \le a$, then effective seed level errors are local stochastic with rate
    \begin{equation}
        q = \left(\frac{p}{p_{\rm RG}}\right)^{c \noisy{\kappa}^{-\ell}}
    \end{equation}
    The same estimate holds jointly for disjoint copies of this three-time gadget whose underlying physical and measurement fault locations are disjoint, even when those faults are correlated.
\end{theorem}
\begin{proof}
    By Remark \ref{rem:cover-equivalence}, it's sufficient to consider a fixed subset of seed level $z$-checks at distinct time steps, i.e., fault locations
    \begin{equation}
        \tau = \bigsqcup_{t} \tau(t) \sqcup \tau(t^+), \quad  \tau(t),\tau(t^+)\subseteq \cZ\super{0}
    \end{equation}
    For exposition purpose, we shall only consider $\tau=\tau(t)$ for a fixed time step $t$ (and thus omitted); the general case can be similarly derived.
    Specifically, we shall upper bound the probability
    \begin{equation}
        \Pr[\tau \text{ covered by } \ubar{E}\super{0}]
    \end{equation}
    where $\ubar{E}\super{0}$ is a to be determined seed level physical, which is stabilizer equivalent to the effective seed level error $E\super{0}$ as defined in Theorem \ref{thm:noise-model-reduction}.
    As before, let us define
    \begin{equation}
        E\super{\ell} = e\super{\ell} +\hat{\cE}(\mu_-\super{\ell})
    \end{equation}
    Consider an increasing sequence $\lambda_{\bullet}$ of admissible subsets relative to $e\super{\ell},\mu_-\super{\ell}$ constructed in some deterministic manner such that the increment $\lambda_i \backslash \lambda_{i-1}$ is a single qubit $q_i$ in $\Lambda(e\super{\ell},\mu_-\super{\ell})$ for each $i$.
    Let
    \begin{equation}
        \noisy{\sigma}\super{\ell}(\lambda_{\bullet}) = \delta E\super{\ell}(\lambda_{\bullet}) + \mu_+\super{\ell}
    \end{equation}
    By Lemma \ref{lem:RG-stability}, if $E\super{0}(\lambda_{\bullet})$ denotes the noisy descent of $E\super{\ell}(\lambda_{\bullet})$ relative to $\mu_+\super{\ell}$, then, modulo stabilizers,
    \begin{equation}
        E\super{\ell} + \hat{\cE}(\noisy{\sigma}\super{\ell}) + \hat{\cE}(\mu_-\super{\ell}) = \sum_{\bullet} h_{\bullet} + \im\delta, \quad h_{\bullet} = E\super{0}(\lambda_\bullet) + E\super{0}(\lambda_{\bullet-1})
    \end{equation}
    Note that by Lemma \ref{lem:RG-stability} and \ref{lem:terminal-dependence}, each difference $h_{\bullet}$ is supported within $\{\succeq w_{\bullet}\}$ (covered by $w_{\bullet}$) at the seed level where $w_{\bullet}\in \cC\super{0}$ is the seed level shadow of $q_{\bullet}$.
    Hence, by local triviality in Remark \ref{rem:setup}, if $\delta h_{\bullet} =0$, then it must be a stabilizer $\in \im \delta$.
    Therefore, we can consider the equivalent representation of the effective seed level physical error
    \begin{equation}
        \ubar{E}\super{0} = \sum_{\bullet: \delta h_{\bullet} \ne 0} h_{\bullet}
    \end{equation}
    Note that if $\noisy{\bm{a}}(\lambda_{\bullet})$ is the noisy history of $\noisy{\sigma}\super{\ell}(\lambda_{\bullet})$, then by Lemma \ref{lem:perturbation} and \ref{lem:active-history}, we have
    \begin{equation}
        \delta h_{\bullet} = \noisy{a}\super{0}(\lambda_{\bullet}) +\noisy{a}\super{0}(\lambda_{\bullet-1})
    \end{equation}
    Hence, removing $h_{\bullet}$ with $\delta h_{\bullet}=0$ from the error $E\super{0}\mapsto \ubar{E}\super{0}$ means that at least one of active histories has a terminal check.
    Note that if $\tau$ is covered by $\ubar{E}\super{0}$ (relative to the induced graph of $C\super{0}$), then it must be covered by $\cB$ (relative to the induced $Z$ graph of $C\super{0}$) as defined in Lemma \ref{lem:admissible-cover}.
    Indeed, if $z\in \tau$, then $z \succ h_i$ for some $\delta h_i\ne 0$. Since $h_i$ is supported in $\{\succeq w_i\}$, we see that $z\succ w_i$.
    Since $\delta h_i \ne 0$, we can assume without loss of generality that there exists $z'$ such that $\noisy{a}\super{0}(\lambda_i)|_{z'}\ne 0$ while $\noisy{a}\super{0}(\lambda_{i-1})|_{z'}= 0$; hence, $z'\in \cB$.
    Since $z' \succ w_i$, we see that $z\in \cN(z')$, where we write $\cN$ for neighborhoods relative to the $Z$ graph, and thus $\tau$ is covered by $\cB$ relative to the $Z$ graph.
    Apply Lemma \ref{lem:admissible-cover} to $\cN(\tau) \cap \cB$, there exists cover $\cS\subseteq \cN(\tau) \cap \cB \subseteq \cN(\tau)$ of $\cN(\tau)\cap \cB$ with 
    \begin{equation}
        \quad \cS\subseteq \noisy{a}\super{0}(\lambda)
    \end{equation}
    for some admissible $\lambda$. 
    Hence, if $\tau$ covered by $\ubar{E}\super{0}$, then there exists admissible $\lambda$ relative to $e\super{\ell},
    \mu_-\super{\ell}$ such that $\cS$ is a subset of terminal checks of $\cJ(\lambda,\mu_+\super{\ell})$, and thus we wish to apply Lemma \ref{lem:terminal-probability}.
    Note, however, that $\cS$ depends on $\tau$ but also the realization of errors $e\super{\ell},\mu_\pm\super{\ell}$, and thus we shall instead consider the following, which is independent of the realization of errors,
    \begin{equation}
        \{\cS\subseteq \cN(\tau): \tau \subseteq \cN_{2}(\cS)\}
    \end{equation}
    Indeed, our argument implies that given $e\super{\ell},\mu_\pm\super{\ell}$ such that $\tau$ is covered by $\ubar{E}\super{0}$, then there exists $\cS$ in the collection such that event $\cA_{\cS}$ occurs. 
    Hence, by Lemma \ref{lem:cover-size} and \ref{lem:terminal-probability}, if $c=\deg \cG_Z(C\super{0})$, which depends only on $\fw,\fd$, then
    \begin{align}
        \Pr[\tau \text{ covered by } \ubar{E}\super{0}] &\le \sum_{\cS} 1\{\cS\subseteq \cN(\tau),\tau \subseteq \cN_2(\cS)\} \Pr[\cA_{\cS}] \\
        &\le 2 q^{|\tau|/c^2} \sum_{\cS} 1\{\cS\subseteq \cN(\tau)\}\\
        &\le 2 q^{|\tau|/c^2} 2^{c|\tau|} 
    \end{align}
    The statement then follows.
\end{proof}

\begin{theorem}[SS Threshold]
    \label{thm:RG-threshold}
    Consider the setup in Remark \ref{rem:setup}, and the noise model in Definition \ref{def:noise-model} such that physical $e\super{\ell}(t)$ and measurement errors $\mu\super{\ell}(t^+)$ for $t\in [0,T]$ in the top level $C\super{\ell}$ are (jointly) local stochastic with rate $p$.
    Then there exists \textbf{threshold} $p_{\rm RG}>0$ and constants $a,c>0$, all of wchich depending only on the constants in Eq. \eqref{eq:constants} (independent of seed decoder), such that if $p/p_{\rm RG} \le a$, then
    \begin{itemize}
        \item If $C\super{0}$ is equipped with an arbitrary meta-check decoder, then the RG decoder satisfies
        \begin{equation}
            \Pr[T \text{ rounds of SS decoding } C\super{\ell} \text{ fails}]= O(T)|\cQ\super{0}| \left(\frac{p}{p_{\rm RG}}\right)^{c\noisy{\kappa}^{-\ell}}
        \end{equation}
        \item If $C\super{0}$ is equipped with a single-shot meta-check decoder, i.e., below threshold $p_c>0$ of the seed decoder,
        \begin{equation}
            \Pr[T \text{ rounds of SS decoding } C\super{0} \text{ fails}] =O(T) \poly (|\cQ\super{0}|) \left(\frac{p}{p_{c}}\right)^{\Omega(n^{\beta})}
        \end{equation}
        then the RG decoder satisfies
        \begin{equation}
            \Pr[T \text{ rounds of SS decoding } C\super{\ell} \text{ fails}]= O(T) \poly(|\cQ\super{0}|) \left(\frac{p}{p_{\rm RG}}\right)^{\Omega(n^{\beta}\noisy{\kappa}^{-\ell})}
        \end{equation}
        provided that $\ell$ is sufficiently large so that
        \begin{equation}
            q = \left(\frac{p}{p_{\rm RG}}\right)^{c \noisy{\kappa}^{-\ell}} < p_c
        \end{equation}
    \end{itemize}
\end{theorem}

\begin{proof}
    By Theorem \ref{thm:noise-transfer}, the probability that the effective seed level errors are nonzero (at least one seed level effective error occurs) is upper bounded by a union bound and thus the first statement follows.
    The case is similar for the second statement.
\end{proof}

