    where $x\otimes v \prec q\otimes e$ if $x\prec q$ in $C$ and $v\prec e$ in repetition $R$, while $q\otimes e \prec z\otimes e$ if $q\prec z$, and $\pi,\iota$ denote the projection and inclusion chain maps.
    From a geometric standpoint, the projection $\pi:Y_2^x \to z\otimes E$ computes the \textbf{flux} (parity) on the $(z,e)$ \textbf{block} as shown in Fig. \ref{fig:Yx-ze-block}, while $\pi:Y_1^x \to q\otimes E$ computes the \textbf{flux} (parity) on each $(q,e)$ \textbf{block}.
\end{remark}

\begin{lemma}[Flux Cleaning]
    \label{lem:flux-cleaning}
    Let $\sigma$ be a 2-coboundary in $Y^x$. For any subset $V'$ of $m-1$ vertices of $V$, there exists $f$ supported on \textit{cone lines} $xq\otimes v$ where $v\in V'$ such that $\sigma +\delta^x f$ has trivial parity in each $(z,e)$ block of $Y^x$; equivalently, the restriction of $\sigma +\delta ^x f$ is a 2-coboundary for each $z$ block.
\end{lemma}

\begin{proof}
    By geometric reduction in Remark \ref{rem:x-geometric-reduction}, if $\sigma\in Y^x$ is a 2-coboundary, i.e., $\in \im \delta^x$, then $\pi \sigma$ must be a 2-coboundary of the embedded column cocomplex.
    In particular, $(\pi \sigma)_e$ can be induced by some $f_e \subseteq \{q:q\succ x\}\times e$ for every edge $e$ of $R$.
    Note that $f_e$ is naturally corresponds to of a subset of 1-cells $\{q\otimes e:q\succ e\}$ in $Y^x$, and thus with slight abuse of notation, we also write $f_e\subseteq \{q\otimes e:q\succ e\}$ so that $(\pi \sigma)_e =\pi f_e$.
    In particular $\pi(\sigma+f_E)=0$ where $f_E$ is the (direct) sum of $f_e,e\in E$.

    Note that $f_e$ is supported on the \textit{rails} $q\otimes e$.
    For our purposes, we would instead prefer a solution concentrated on the \textit{cone lines} $xq\otimes v$.
    To do this, note that for any fixed $q$, the collection $f_E(q)\equiv \{f_e(q):e\}$ can be regarded a subset of edges of $R$ and since $H_1(R)=0$, there must exist subset $f_V(q)\equiv \{f_v(q):v\}$ of vertices such that $\delta^R f_V(q)= f_E(q)$.
    In fact, we can choose $f_V(q)$ to be supported on any $m-1$ vertices uniformly over $q$.
    With slight abuse of notation, write $f_V$ as the sum of cone lines $xq\otimes v$ if $f_v(q)\ne 0$, and thus it's straightforward to check that $\pi f_E=\pi f_V$ so that $\pi (\sigma +f_V)=0$.
\end{proof}

The purpose of Lemma \ref{lem:flux-cleaning} is so that one may focus on a single $z$ block of $Y^x$.
\begin{lemma}[$z$ Block Cleaning]
    \label{lem:z-block-cleaning}
    Let $\sigma$ be a 2-coboundary of a fixed $z$ block in $Y^x$.
    Then there exists 1-chain $f$ supported on hinges\footnote{For $m=3$, there is no loss in generality considering $f$ supported only on hinges $qz\otimes v$. Indeed, if $f$ is supported on some rail $z\otimes e$, then it contributes $+2$ to $|g^{Qx} f|$.
    This is equivalent to instead assigning $f$ a support on hinges $q^\pm z\otimes v$ where $v\prec e$ is the leaf of the $m=3$ repetition code, since each hinge contributes $+1$ to $|g^{Qx} f|$.} $qz\otimes v$ (but not on \textit{rails} $z\otimes e$) of the $z$ block such that $\delta^x f =\sigma$ and
    \begin{equation}
        |g^{Qx} f| \le 
        \begin{cases}
            \min ( |c^+|+|c^-|, 2m -|c^+|-|c^-|) & \beta =0 \\
            m - ||c^+|-|c^-|| & \beta =1
        \end{cases}
    \end{equation}
    where $c^\pm, \beta$ are defined via $\sigma$ as follows.
    Let $q^\pm$ denote the qubits in the $z$ block, i.e., $x\prec q^\pm \prec z$. 
    Choose a reference vertex $v_0$ on the repetition graph and let $\beta \in \F_2$ be the value of $\sigma$ on $xz\otimes v_0$. 
    Let $c_v^\pm \in \F_2$ be the summation of $\sigma$ on $q^\pm z\otimes e$ over edges $e$ along the unique path from $v_0 \to v$ in $R$ so that $c^\pm \in V$.
\end{lemma}

\begin{proof}
    For notation simplicity, let $\sigma_v$ denote the value of $\sigma$ on $xz\otimes v$; similarly, let $f_v^\pm$ denote the value of $f$ on $q^\pm z\otimes v$.
    Since $\sigma$ has zero parity on each $(z,e)$ block, we see that $\beta_v \equiv c_v^- +c_v^+ +\sigma_v$ is a constant for all $v$ and equal to $\beta$.
    Also note that by definition, if $\delta^x f=\sigma$, then for any edge $vv'$ of the repetition code, we must have
    \begin{equation}
        f_v^\pm +f_{v'}^{\pm} = c_v^\pm +c_{v'}^{\pm}
    \end{equation}
    Hence, using the reference point $v_0$, we see that for any vertex $v$,
    \begin{equation}
        f_v^\pm =f_{v_0}^\pm +c_v^\pm
    \end{equation}
    Also note that if we desire $\delta^x f =\sigma$, then $f_{v_0}^+ +f_{v_0}^-=\beta$.
    The converse is also clear, i.e., any $f$ of the form $f^\pm =c^\pm +\beta^\pm \cV$ where $\cV$ denotes the subset of all vertices in $V$ with $\beta^+ +\beta^- =\beta$ satisfies $\delta^x f=\sigma$ and is supported on hinges $qz\otimes v$.
    In particular, due to the gluing in Definition \ref{def:gluing}, we see that
    \begin{align}
        |g^{Qx} f| =|f| &=\min_{\beta^+ +\beta^-=\beta} (|c^+ +\beta^+ \cV| +|c^-+\beta^- \cV|)
    \end{align}
    And thus the statement follows by considering the cases $\beta=0,1$ separately.
\end{proof}

\begin{theorem}[$x$ Layer Cleaning]
    \label{thm:x-layer-cleaning}
    Let $\sigma$ be a 2-coboundary of $Y^x$ with $m=3$. Then there exists $f$ supported on $Y^x$, but not on \textit{rails} $z\otimes e$ for any $z\succ x$ and $e\in E$, such that $\delta^x f= \sigma$ and
    \begin{equation}
        |g^{Qx} f| \le \frac{9}{7} |\sigma|
    \end{equation}
    In particular, $\zeta^{QX}\le 9/7$
\end{theorem}

\begin{proof}
    Fix a reference vertex $v^\star$ of $R$.
    By Lemma \ref{lem:flux-cleaning}, there exists $f^{\star}$ supported on cone lines $xq\otimes v$ with $v\ne v^{\star}$ such that $\sigma +\delta^x f^{\star}$ is a 2-coboundary for each $z$ block, whose restriction we denote as $\hat{\sigma}^z$.
    By Lemma \ref{lem:z-block-cleaning}, we can find $f^z$ supported on hinges in the $z$ block such that $\hat{\sigma}^z=\delta^x f^z$.
    Moreover, let $v^{\star}$ be the reference point to upper bound $|g^{Qx} f^z|$.
    Note that by using the same reference point $v^{\star}$ for both Lemma \ref{lem:flux-cleaning} and \ref{lem:z-block-cleaning}, we see that
    \begin{equation}
        \hat{\sigma}^z_e=\sigma^z_e,\quad \hat{\sigma}^z_{v^{\star}} =\sigma^z_{v^{\star}}
    \end{equation}
    where the subscripts denote the restriction of $\hat{\sigma}^z$ (or $\sigma^z$) to the corresponding face, e.g., $\hat{\sigma}^z_{e}$ is that on $qz\otimes e,q\succ z$ and $\hat{\sigma}^z_{v}$ is that on $xz\otimes v$.
    Hence,
    \begin{equation}
        |g^{Qx} f^z| \le 
        \begin{cases}
            2|\sigma^z_{01}| +  |\sigma^z_{12}| +3|\sigma^z_0| & v^{\star} =v_0  \\
            |\sigma^z_{01}| +  |\sigma^z_{12}| +3|\sigma^z_1| & v^{\star} =v_1  \\
            |\sigma^z_{01}| +  2|\sigma^z_{12}| +3|\sigma^z_2| & v^{\star} =v_2
        \end{cases}
    \end{equation}
    Where $v_0,v_1,v_2$ are the $m=3$ vertices of $R$ and $v_0,v_2$ are the leaves and $v_1$ is the center vertex.
    Let
    \begin{equation}
        f =f^{\star} +\sum_{z\succ x} f^z
    \end{equation}
    Since $g^{Qx} f^{\star}=0$, we see that $\delta^x f=\sigma$ and
    \begin{equation}
        |g^{Qx} f| \le 
        \begin{cases}
            2|\sigma_{01}| +  |\sigma_{12}| +3|\sigma_0| & v^{\star} =v_0  \\
            |\sigma_{01}| +  |\sigma_{12}| +3|\sigma_1| & v^{\star} =v_1  \\
            |\sigma_{01}| +  2|\sigma_{12}| +3|\sigma_2| & v^{\star} =v_2
        \end{cases}
    \end{equation}
    Note that the reference $v^{\star}$ can be arbitrarily chosen, and instead of taking the minimum over the three options, we can take the average, with weighted options $2/7,3/7,2/7$ so that the statement then follows.
\end{proof}

