\end{remark}

\begin{lemma}[Flux Freedom]
    \label{lem:flux-freedom}
    If $\sigma$ is a 1-coboundary in $Y^q$, then the flux of $\sigma$ on $(z,e)$ blocks is constant over all $z\succ q$ for fixed $e$.
    In particular, there exists a bijection between 1-coboundaries $\sigma$ of $Y^q$ and $(\Phi,r_z,z\succ q)$ where $\Phi\in E,r_z\in V$, so that $\Phi$ is the flux of $\sigma$ and $r_z$ is the restriction of $\sigma$ on \textit{cone lines} $qz\otimes V$.
\end{lemma}
\begin{proof}
    Follows trivially from the homotopy equivalence between $Y^q$ and $q\otimes V\to z\otimes E$.
\end{proof}

\begin{theorem}[$q$ Layer Cleaning]
    \label{thm:q-layer-cleaning}
    Let $\sigma$ be a 1-coboundary of $Y^q$. If $m=3$, then
    \begin{equation}
        \|\sigma\|^{ZQ} |\sigma|\le |\sigma|_{\rm spokes} + \frac{4}{3}|\sigma|_{\rm rails}
    \end{equation}
    where $|\sigma|_{\rm spokes},|\sigma|_{\rm rails}$ denotes the weights of $\sigma$ restricted to spokes $qz\otimes v$ and rails $z\otimes e$, respectively.
    In particular, $\zeta^{ZQ}\le 4/3$.
\end{theorem}



\begin{proof} 
    By Lemma \ref{lem:flux-freedom}, we see that a 1-coboundary $\sigma$ is specified by $(\Phi,r_z,z\succ q)$.
    Hence, $f$ is a 0-chain in $Y^q$ such that $\delta^q f=\sigma$ iff
    \begin{align}
        f_{z,v} &= r_{z,v} + f_{q,v} \\
        f_{q,v} &= f_{q,v^{\star}} + \sum_{e\in v^{\star} \to v} \Phi_e
    \end{align}
    where $v^{\star}$ is some chosen fixed reference vertex in $R$ and $v^{\star} \to v$ is the unique path in $R$ connecting the two vertices.
    In particular, we see that $f$ is unique up to freedom $f_{q,v^{\star}}\in \F_2$, which also follows from $H^0(Y^q) \cong \F_2$.
    Let
    \begin{equation}
        y_v = \sum_{e\in v^{\star}\to v} \Phi_e
    \end{equation}
    so that $\Phi \mapsto y$ is injective with the image being $y\in V$ such that $y_{v^{\star}}=0$. 
    Set $u_z= r_z+y$ and define the total change of $u_z$ as
    \begin{equation}
        \ch u_z \equiv \sum_{e=vv'\in E} |u_{z,v} + u_{z,v'}|
    \end{equation}
    Then it's straightforward to check that
    \begin{equation}
        \|\sigma\|^{ZQ} = \frac{1}{|\sigma|}\min\left(\sum_{z\succ q} |u_z|, \sum_{z\succ q} (3-|u_z|)\right)
    \end{equation}
    where
    \begin{equation}
        |\sigma| = \sum_{z\succ q} (|u_z+y| +\ch u_z)
    \end{equation}
    Note that
    \begin{equation}
        \min\left(\sum_{z\succ q} |u_z|, \sum_{z\succ q} (m-|u_z|)\right) \le \sum_{z\succ q} (\lambda |u_z| +(1-\lambda)(3-|u_z|))
    \end{equation}
    Choose $\lambda = 1-|y|/m$. Then
    \begin{equation}
        |\sigma|\|\sigma\|^{ZQ} \le \sum_{z\succ q} \left(|y| + \left(1-\frac{2}{3} |y|\right) |u_z|\right)
    \end{equation}
    Then it's sufficient to show that for any 1-chain $u\in V$, we have
    \begin{equation}
        |y| + \left(1-\frac{2}{3} |y|\right) |u_z| \le |u+y| +\frac{4}{3} \ch u
    \end{equation}
    Equivalently, it's sufficient to  show that
    \begin{equation}
        3 |u\cap y| -|u| |y| \le 2 \ch u 
    \end{equation}
    where we note that the left side is the covariance $3\Cov(u,y)$ between $u,y$ vectors.
    By symmetry between $y$ and $y+\cV$, it's sufficient to consider the cases where $|y|=0,1$. 
    The former case is trivial and thus we are only left with the singleton case $|y|=1$.
    In this case, if $u$ is a uniform constant so that $\ch u=0$, then it's clear that $\Cov(u,y)=0$ and thus the inequality holds. 
    Conversely, if $\ch u\ne 0$, then we see that the left-side is $\le 2$ and thus the inequality holds.
    Hence, the statement follows.
\end{proof}

\begin{remark}[Tightness]
    Since the local graph of $q$ is simply a set of disjoint vertices, one can further obtain $\zeta^{ZQ}$ for arbitrary $m\ge 2$ as follows.
    \begin{equation}
        \zeta^{ZQ} = 
        \begin{dcases}
            \left\lfloor \frac{m}{2} \right\rfloor & m\ne 3 \\
            \frac{6}{5} & m=3
        \end{dcases}
    \end{equation}
    The proof follows similarly to Theorem \ref{thm:q-layer-cleaning} but optimizes the constant using linear programming (LP).
    Since we do not use this fact, we omit the proof.
\end{remark}

\subsection{$x,q$ Cleaning}

\begin{theorem}[Contraction]
    \label{thm:contraction}
    Let $\Gamma$ be constructed with $m=3$. Then there exists a layer-local map $f$ which maps clean syndromes $\sigma \in \ker\bar{\delta}$ to qubits  such that
    \begin{equation}
        \sigma +\delta f(\sigma) \in \im \iota
    \end{equation}
    so that the \textbf{descent} $\desc \sigma = \pi (\sigma+\delta f(\sigma))$ is a syndrome in $C$, and 
    \begin{equation}
        |\desc\sigma| \le \kappa |\sigma|, \quad \kappa = \frac{4}{9} < \frac{1}{2}
    \end{equation}
    Moreover, $f(\sigma +\iota \noisy{\tau}) =f(\sigma)$ for any syndrome $\noisy{\tau}$ in $C$.
\end{theorem}

\begin{remark}[Single-Step Contraction]
    Follow the proof of Theorem \ref{thm:contraction}, as discussed previously, one may deduce a factor $\kappa = \zeta^{ZQ} \zeta^{QX}/m$ by a two step cleaning procedure.
    However, by Theorem \ref{thm:x-layer-cleaning} and Theorem \ref{thm:q-layer-cleaning}, this would result in $\kappa > 1/2$ for $m=3$. 

    Hence, we optimize for the slightly more convoluted statements of Theorem \ref{thm:x-layer-cleaning} and \ref{thm:q-layer-cleaning}.
\end{remark}
\begin{proof}
    Let $\sigma= \sigma$ be a meta-check clean syndrome in $\Gamma$.
    By Definition \ref{def:gluing}, the restriction $\sigma|^x$ to the $x$-layer must be a 2-cocycle of $Y^x$.
    Since $Y^x$ is contractible, we see that it must also be a 2-coboundary and thus by Theorem \ref{thm:x-layer-cleaning}, there exists $f^x$ supported on $Y^x$, but not on rails $z\otimes e$, such that $\delta^x f=\sigma^x$ and
    \begin{equation}
        |g^{Qx} f^x| \le \frac{9}{7} |\sigma^x|
    \end{equation}
    Let $f^X$ denote the sum of $f^x$ over all $x\in X\super{i-1}$ and note that $\sigma^1=\sigma +\delta f^X$ has zero support on $x$-layers, while its restriction $\sigma^1|^q$ to a $q$ layer must be a 1-cocycle of $Y^q$.
    Since $Y^q$ is contractible, it must also be a 1-coboundary and thus by Theorem \ref{thm:q-layer-cleaning}, we see that there exists $f^q$ supported on $Y^q$ such that $\delta^q f^q=\sigma^1|^q$ and
    \begin{equation}
        |g^{Zq}f^q|\le |\sigma^1|^q|_{\rm spokes} +\frac{4}{3} |\sigma^1|^q|_{\rm rails}
    \end{equation}
    Note that by Theorem \ref{thm:x-layer-cleaning}, $\sigma^1|^q$ and $\sigma^q$ are equal on rails. Hence,
    \begin{equation}
        |g^{Zq}f^q|\le |\sigma|^q + g^{qX} f^X|_{\rm spokes} +\frac{4}{3} |\sigma|^q|_{\rm rails}
    \end{equation}
    Let $f^Q$ be the sum of $f^q$ over all qubits $q$ in $C$ and let $f=f^X+f^Q$.
    It's then clear that $\sigma\mapsto f$ is layer local and $\sigma^2 \equiv \sigma +\delta f$ is only supported on $z$ layers.
    Hence, we see that
    \begin{align}
        |\sigma^2| &= \sum_z |\sigma^2|^z \\ 
        &\le \sum_z |\sigma|^z +\sum_{q} |g^{Zq} f^q| \\
        &\le |\sigma|^Z + \sum_{q} |\dnum^q \sigma + g^{qX} f^X|_{\rm spokes} +\frac{4}{3} |\sigma|^q_{\rm rails} \\
        &\le |\sigma|^Z + \frac{4}{3} |\sigma|^Q + \sum_x |g^{Qx} f^x|  \\
        &\le |\sigma|^Z + \frac{4}{3} |\sigma|^Q + \frac{9}{7}|\sigma|^X  \\
        &\le \frac{4}{3} |\sigma|
    \end{align}
    Also note that $\sigma+\delta f\in \ker \bar{\delta}$ and thus by Definition \ref{def:gluing} must be in the image of the inclusion map $\iota$ so that
    \begin{equation}
        \sigma +\delta f =\iota \sigma'
    \end{equation}
    for some syndrome $\sigma'$ in $C$. Since $|\iota \sigma'| =3|\sigma'|$, we see that the inequality follows.
    Note that if $\sigma$ is a valid syndrome (not just meta-check clean), then $\sigma =\delta e$ for some $e$. Hence,
    \begin{equation}
        \sigma' = \delta \pi (e+f) \in \im \delta
    \end{equation}
    Hence, $\sigma'$ is a valid syndrome in $C$.
    Also note that by definition, $f$ satisfies the passthrough property in Definition \ref{def:cleaning}.
\end{proof}

\subsection{Fill Bound}

As suggested by Definition \ref{def:level-map}, we must obtain the fill bound factor $c_f$.

\begin{theorem}[Fill Bound]
    \label{thm:fill-bound}
    Let $f$ be the cleaning map in Theorem \ref{thm:contraction} for $\Gamma$. Then for any clean syndrome $\sigma$ with $f=f(\sigma)$,
    \begin{equation}
        |\sh \{\succeq f\} \backslash \sh \sigma| \le |\sh f(\sigma) \backslash \sh \sigma| \le c_f |\sigma|
    \end{equation}
    where $c_f<3$
\end{theorem}

\begin{proof}
    Note that
    \begin{align}
        |\sh \{\succeq f\} \backslash \sh \sigma| &= \sum_{u} 1\{u\in \sh\{\succeq f\},\sigma|^u =0\} \\
        &= \sum_{u=q,z} 1\{u\in \sh\{\succeq f\},\sigma|^u =0\}
    \end{align}
    where we do not need to consider $x$ checks since if $\sigma|^x=0$, then by layer-locality, we have $f|^x=0$.
    First consider $u=q$. If $q\in \sh\{\succeq f\}$, then we see that either $f|^q\ne 0$ or there exists $x\prec q$ such that $g^{qx} f|^x\ne 0$.
    Since $\sigma|^q=0$, we see that if $g^{qX} f|^X=0$, then by construction, we would have chosen $f|^q=0$ and thus either possibility would imply that there exists $x\prec q$ such that $g^{qx} f|^x\ne 0$.
    Hence,
    \begin{align}
        \sum_{q} 1\{q\in \sh\{\succeq f\},\sigma|^q=0\} &\le \sum_{q} \sum_{x\prec q} 1\{ g^{qx} f|^x\ne 0,\sigma|^q=0\} \\
        &\le \sum_{x} \sum_{q\succ x} |g^{qx} f^X| \\
        &\le \frac{9}{7} |\sigma^X|
    \end{align}
    Now consider $u=z$. By definition, if $z\in \sh\{\succeq f\}$, then $g^{zq}f|^q\ne0$ for some $q\prec z$. Hence,
    \begin{align}
        \sum_{z} 1\{z\in \sh\{\succeq f\},\sigma|^z=0\} &\le \sum_{z} |g^{zQ} f^Q| 1\{\sigma|^z=0\} \\
        &\le |\iota \desc \sigma| \\
        &\le \frac{4}{3} |\sigma|
    \end{align}
    Combining the two results in $c_f = 4/3+ 9/7 <3$
\end{proof}

